func TestLib_CustomActions_GetterShouldReturnDefaultValue(t *testing.T) {
	node := NewNode(RoleUnknown)
	assertEmpty(t, node.CustomActions())
}

func TestLib_CustomActions_SetterShouldUpdateTheProperty(t *testing.T) {
	node := NewNode(RoleUnknown)
	value := []CustomAction{{ID: 0, Description: "first test action"}, {ID: 1, Description: "second test action"}}
	node.SetCustomActions(slices.Clone(value))
	if got := node.CustomActions(); !slices.Equal(got, value) {
		t.Fatalf("got %v", got)
	}
}

func TestLib_CustomActions_PusherShouldUpdateTheProperty(t *testing.T) {
	node := NewNode(RoleUnknown)
	first := CustomAction{ID: 0, Description: "first test action"}
	second := CustomAction{ID: 1, Description: "second test action"}
	node.PushCustomAction(first)
	if got := node.CustomActions(); !slices.Equal(got, []CustomAction{first}) {
		t.Fatalf("got %v", got)
	}
	node.PushCustomAction(second)
	if got := node.CustomActions(); !slices.Equal(got, []CustomAction{first, second}) {
		t.Fatalf("got %v", got)
	}
}

func TestLib_CustomActions_ClearerShouldResetTheProperty(t *testing.T) {
	node := NewNode(RoleUnknown)
	node.SetCustomActions([]CustomAction{{ID: 0, Description: "test action"}})
	node.ClearCustomActions()
	assertEmpty(t, node.CustomActions())
}

